// <auto-generated />
namespace LiveScore.WebApi.Shared.Middlewares
{
    using LiveScore.Soccer.Configurations;
    using LiveScore.Soccer.Database;
    using Microsoft.AspNetCore.Builder;
    using Microsoft.EntityFrameworkCore;
    using Microsoft.Extensions.Configuration;
    using Microsoft.Extensions.DependencyInjection;
    using Microsoft.Extensions.Logging;

    public static class DataBaseMiddleware
    {
        public static void AddDatabase(this IServiceCollection services, IConfiguration configuration)
        {
            var loggerFactory = services.BuildServiceProvider().GetService<ILoggerFactory>();

            services.AddEntityFrameworkNpgsql()
                   .AddDbContext<ScoreAppContext>(options
                        => options
                            .UseNpgsql(configuration.GetConnectionString("DefaultConnection"))
                            .EnableSensitiveDataLogging()
                            .UseLoggerFactory(loggerFactory))
                   .BuildServiceProvider();

            services.AddScoped<IDynamicRepository, DynamicRepository>();
        }

        public static void UseDatabase(this IApplicationBuilder app)
        {
            var appSettings = app.ApplicationServices.GetService<IAppSettings>();

            if (appSettings.EnabledDatabaseMigration)
            {
                using (var scope = app.ApplicationServices.GetService<IServiceScopeFactory>().CreateScope())
                {
                    scope.ServiceProvider.GetRequiredService<ScoreAppContext>().Database.Migrate();
                }
            }
        }
    }
}